"use client";

import { useEffect, useState } from "react";
import { Download, Play, X } from "lucide-react";

type DownloadModalProps = {
  isOpen: boolean;
  isoName: string;
  onClose: () => void;
};

export function DownloadModal({
  isOpen,
  isoName,
  onClose,
}: DownloadModalProps) {
  const [isDownloading, setIsDownloading] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (!isOpen) return;
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") onClose();
    }
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  useEffect(() => {
    if (!isOpen || !isDownloading) return;
    const interval = window.setInterval(() => {
      setProgress((current) => {
        return Math.min(current + Math.floor(Math.random() * 15) + 5, 100);
      });
    }, 250);
    return () => window.clearInterval(interval);
  }, [isDownloading, isOpen]);

  useEffect(() => {
    if (progress === 100) setIsDownloading(false);
  }, [progress]);

  useEffect(() => {
    if (!isOpen || progress < 100) return;
    const timeout = window.setTimeout(onClose, 2000);
    return () => window.clearTimeout(timeout);
  }, [isOpen, onClose, progress]);

  useEffect(() => {
    if (isOpen) {
      setProgress(0);
      setIsDownloading(false);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  function closeModal() {
    setIsDownloading(false);
    setProgress(0);
    onClose();
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/80 p-4 backdrop-blur-md"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) closeModal();
      }}
    >
      <section
        role="dialog"
        aria-modal="true"
        aria-labelledby="download-dialog-title"
        className="relative w-full max-w-lg animate-fade-in rounded-3xl border border-slate-800 bg-slate-900 p-6 shadow-2xl sm:p-8"
      >
        <button
          type="button"
          onClick={closeModal}
          aria-label="Close download dialog"
          className="absolute right-5 top-5 p-2 text-slate-400 hover:text-white"
        >
          <X className="h-5 w-5" />
        </button>

        <div className="mb-6 flex items-center gap-3">
          <div className="rounded-xl bg-debian/10 p-3 text-debian">
            <Download className="h-6 w-6" />
          </div>
          <div>
            <h3 id="download-dialog-title" className="text-xl font-bold text-white">
              Download Debian ISO
            </h3>
            <p className="text-xs text-slate-400">
              Direct download mirror simulator
            </p>
          </div>
        </div>

        <div className="mb-6 space-y-4">
          <div className="space-y-2 rounded-xl border border-slate-800 bg-slate-950 p-4">
            <div className="flex justify-between gap-4 text-xs text-slate-400">
              <span>Selected Target:</span>
              <span className="break-all text-right font-mono font-semibold text-debian">
                {isoName}
              </span>
            </div>
            <div className="flex justify-between gap-4 text-xs text-slate-400">
              <span>Mirror Location:</span>
              <span className="text-right text-slate-200">
                Global Fast CDN (Auto-detected)
              </span>
            </div>
          </div>

          {(isDownloading || progress > 0) && (
            <div className="space-y-2" aria-live="polite">
              <div className="flex justify-between font-mono text-xs">
                <span
                  className={
                    progress === 100 ? "text-green-400" : "text-slate-300"
                  }
                >
                  {progress === 100
                    ? "Download Complete! Check Downloads folder."
                    : "Downloading ISO..."}
                </span>
                <span className="font-bold text-debian">{progress}%</span>
              </div>
              <div
                role="progressbar"
                aria-label="Download progress"
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={progress}
                className="h-2.5 w-full overflow-hidden rounded-full border border-slate-800 bg-slate-950"
              >
                <div
                  className="h-full bg-debian transition-all duration-300"
                  style={{ width: `${progress}%` }}
                />
              </div>
            </div>
          )}
        </div>

        <div className="flex gap-3">
          <button
            type="button"
            onClick={() => {
              setProgress(0);
              setIsDownloading(true);
            }}
            disabled={isDownloading || progress === 100}
            className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-debian py-3 font-bold text-white transition-all hover:bg-debian-hover disabled:cursor-not-allowed disabled:opacity-60"
          >
            <Play className="h-4 w-4" />
            <span>{progress === 100 ? "Download Complete" : "Start Download"}</span>
          </button>
          <button
            type="button"
            onClick={closeModal}
            className="rounded-xl border border-slate-800 px-5 text-sm font-semibold text-slate-300 hover:text-white"
          >
            Cancel
          </button>
        </div>
      </section>
    </div>
  );
}
