"use client";

import { useEffect, useRef, useState } from "react";
import { PlayCircle, Terminal } from "lucide-react";

type CommandType = "install" | "upgrade" | "neofetch";

const commandLabels: Record<CommandType, string> = {
  install: "sudo apt update && apt install nginx",
  upgrade: "sudo apt full-upgrade",
  neofetch: "fastfetch",
};

function Prompt() {
  return (
    <span>
      <span className="font-bold text-debian">user@debian-server</span>:
      <span className="text-blue-400">~</span>$
    </span>
  );
}

function CommandOutput({ command }: { command: CommandType }) {
  if (command === "install") {
    return (
      <>
        <div className="text-slate-400">
          Hit:1 http://deb.debian.org/debian bookworm InRelease
        </div>
        <div className="text-slate-400">
          Get:2 http://security.debian.org/debian-security bookworm-security
          InRelease [48.0 kB]
        </div>
        <div className="text-slate-400">Reading package lists... Done</div>
        <div className="text-slate-400">Building dependency tree... Done</div>
        <div className="text-green-400">Setting up nginx (1.22.1-9) ... Done</div>
        <div className="text-slate-400">Service nginx starting... [ OK ]</div>
      </>
    );
  }

  if (command === "upgrade") {
    return (
      <>
        <div className="text-slate-400">Calculating upgrade... Done</div>
        <div className="text-slate-400">
          0 upgraded, 0 newly installed, 0 to remove and 0 not upgraded.
        </div>
        <div className="text-green-400">
          System is completely up to date!
        </div>
      </>
    );
  }

  return (
    <pre className="overflow-x-auto whitespace-pre font-mono font-bold leading-tight text-debian">
      {`   _____          OS: Debian GNU/Linux 12 (bookworm) x86_64
  / __  \\         Host: KVM Virtual Machine
 | /  | |         Kernel: 6.1.0-21-amd64
 | |__| |         Uptime: 42 days, 13 hours
  \\_  ___/        Packages: 1420 (dpkg)
   / /            Shell: bash 5.2.15
  / /             Memory: 2048MiB / 8192MiB`}
    </pre>
  );
}

export function TerminalDemo() {
  const [commands, setCommands] = useState<CommandType[]>([]);
  const screenRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const screen = screenRef.current;
    if (screen) screen.scrollTop = screen.scrollHeight;
  }, [commands]);

  function runCommand(command: CommandType) {
    setCommands((current) => [...current, command]);
  }

  return (
    <section
      id="terminal-demo"
      className="border-y border-slate-800/80 bg-slate-900/30 py-20"
    >
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 items-center gap-12 lg:grid-cols-12">
          <div className="lg:col-span-5">
            <div className="mb-3 inline-flex items-center gap-2 text-sm font-semibold text-debian">
              <Terminal className="h-4 w-4" />
              <span>APT Package Manager</span>
            </div>
            <h3 className="mb-4 text-3xl font-extrabold text-slate-100 dark:text-white light:text-slate-900">
              Simplicity and Power at the Command Line
            </h3>
            <p className="mb-6 text-base leading-relaxed text-slate-400">
              Debian&apos;s legendary{" "}
              <code className="rounded bg-debian/10 px-1.5 py-0.5 font-mono text-sm text-debian">
                apt
              </code>{" "}
              tool makes managing packages, dependencies, and system upgrades
              seamless and reliable.
            </p>
            <div className="space-y-3">
              {(Object.keys(commandLabels) as CommandType[]).map((command) => (
                <button
                  type="button"
                  key={command}
                  onClick={() => runCommand(command)}
                  className="group flex w-full items-center justify-between rounded-xl border border-slate-800 bg-slate-900/80 p-3.5 text-left transition-all hover:border-debian/50 dark:border-slate-800 dark:bg-slate-900/80 light:border-slate-300 light:bg-white"
                >
                  <span className="font-mono text-sm text-slate-300 dark:text-slate-300 light:text-slate-700">
                    {commandLabels[command]}
                  </span>
                  <PlayCircle className="h-5 w-5 shrink-0 text-slate-500 group-hover:text-debian" />
                </button>
              ))}
            </div>
          </div>

          <div className="lg:col-span-7">
            <div className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-950 font-mono text-sm shadow-2xl">
              <div className="flex items-center justify-between border-b border-slate-800 bg-slate-900 px-4 py-3">
                <div className="flex items-center gap-2">
                  <span className="h-3 w-3 rounded-full bg-red-500/80" />
                  <span className="h-3 w-3 rounded-full bg-yellow-500/80" />
                  <span className="h-3 w-3 rounded-full bg-green-500/80" />
                  <span className="ml-2 text-xs text-slate-400">
                    user@debian-server: ~
                  </span>
                </div>
                <span className="text-xs text-slate-500">bash</span>
              </div>
              <div
                ref={screenRef}
                role="log"
                aria-live="polite"
                aria-label="Terminal output"
                className="h-80 space-y-2 overflow-y-auto p-6 leading-relaxed text-slate-300"
              >
                <div className="text-slate-500">
                  # Welcome to Debian Linux Interactive Shell
                </div>
                <div className="text-slate-500">
                  # Click one of the buttons on the left to simulate APT commands.
                </div>
                {commands.map((command, index) => (
                  <div key={`${command}-${index}`}>
                    <div>
                      <Prompt /> {commandLabels[command]}
                    </div>
                    <CommandOutput command={command} />
                    <div>
                      <Prompt /> <span className="animate-pulse">_</span>
                    </div>
                  </div>
                ))}
                {commands.length === 0 && (
                  <div>
                    <Prompt /> <span className="animate-pulse">_</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
